/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/avatar.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
"use client";

import * as React from "react";
import { Avatar as AvatarPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Avatar({
  className,
  size = "default",
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & {
  size?: "default" | "sm" | "lg";
} & CapconsBasePropsLoose) {
  return <AvatarPrimitive.Root data-slot="avatar" data-size={size} className={cn("group/avatar relative flex size-8 shrink-0 overflow-hidden rounded-full select-none data-[size=lg]:size-10 data-[size=sm]:size-6", className)} {...capconsSpread(props)} />;
}
function AvatarImage({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Image> & CapconsBasePropsLoose) {
  return <AvatarPrimitive.Image data-slot="avatar-image" className={cn("aspect-square size-full", className)} {...capconsSpread(props)} />;
}
function AvatarFallback({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Fallback> & CapconsBasePropsLoose) {
  return <AvatarPrimitive.Fallback data-slot="avatar-fallback" className={cn("flex size-full items-center justify-center rounded-full bg-muted text-sm text-muted-foreground group-data-[size=sm]/avatar:text-xs", className)} {...capconsSpread(props)} />;
}
function AvatarBadge({
  className,
  ...props
}: React.ComponentProps<"span"> & CapconsBasePropsLoose) {
  return <span data-slot="avatar-badge" className={cn("absolute right-0 bottom-0 z-10 inline-flex items-center justify-center rounded-full bg-primary text-primary-foreground ring-2 ring-background select-none", "group-data-[size=sm]/avatar:size-2 group-data-[size=sm]/avatar:[&>svg]:hidden", "group-data-[size=default]/avatar:size-2.5 group-data-[size=default]/avatar:[&>svg]:size-2", "group-data-[size=lg]/avatar:size-3 group-data-[size=lg]/avatar:[&>svg]:size-2", className)} {...capconsSpread(props)} />;
}
function AvatarGroup({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="avatar-group" className={cn("group/avatar-group flex -space-x-2 *:data-[slot=avatar]:ring-2 *:data-[slot=avatar]:ring-background", className)} {...capconsSpread(props)} />;
}
function AvatarGroupCount({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="avatar-group-count" className={cn("relative flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm text-muted-foreground ring-2 ring-background group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=sm]/avatar-group:size-6 [&>svg]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg]:size-3", className)} {...capconsSpread(props)} />;
}
export { Avatar, AvatarImage, AvatarFallback, AvatarBadge, AvatarGroup, AvatarGroupCount };
